(async()=>{
'use strict';
if(document.documentElement.dataset.rentproDemo!=='true'&&new URLSearchParams(location.search).get('demo')==='1'){rpStore.ready.catch(()=>{});location.replace(new URL('demo.html'+(location.hash||'#overview'),location.href).href);return;}
const $=id=>document.getElementById(id),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),M=v=>Number(v||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}),C=RP.clone;
const today=RentModel.todayISO(),uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2),now=()=>new Date().toISOString(),names={overview:'ภาพรวม',billing:'ทำบิลรายเดือน',payments:'รับชำระ',properties:'ห้องและผู้เช่า',settings:'ตั้งค่า'};
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',billing:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 7h6M9 11h6M9 15h4"/>',payments:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h3"/>',properties:'<path d="M3 21V9l9-6 9 6v12M8 21V11h8v10M3 21h18M8 15h8"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',water:'<path d="M12 3c-2 4-7 8-7 12a7 7 0 0 0 14 0c0-4-5-8-7-12z"/>',electric:'<path d="m13 2-9 12h7l-1 8 10-13h-8z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=k=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[k]||icons.properties)+'</svg>';
let db,demo=false,page=['overview','billing','payments','properties','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'overview',period=today.slice(0,7),stage=1,selectedRoom='',search='',filter='all',allPeriods=false,settingsTab='owner',working=null,modalData={},busy=false,cloudReady=false,cloudError='',fb=null,syncTimer,base,knownBase=false;
const forceDemo=document.documentElement.dataset.rentproDemo==='true'||new URLSearchParams(location.search).get('demo')==='1';
try{await rpStore.ready;let real=null;if(!forceDemo){let raw=rpStore.getItem('rentpro_v2');if(raw)real=JSON.parse(raw);if(real)RP.migrate(real);if(real&&!rpStore.getItem('rentpro_backup_before_v4'))rpStore.setItem('rentpro_backup_before_v4',JSON.stringify({at:now(),data:real}));}let meaningful=real&&(real.tenants.length||real.contracts.length||real.payments.length||(real.fbcfg||{}).projectId),mode=new URLSearchParams(location.search).get('mode')||rpStore.getItem('rentpro_v4_mode');demo=forceDemo||(mode?mode==='demo':!meaningful);if(demo){let raw=rpStore.getItem('rentpro_demo_v4');try{db=raw?JSON.parse(raw):null;}catch{db=null;}if(!db||!Array.isArray(db.rooms)||!Array.isArray(db.tenants)||!Array.isArray(db.contracts)||[1,2,3,4].some(n=>!db.rooms.some(r=>r.id==='sample-room-'+n)||!db.tenants.some(t=>t.id==='sample-tenant-'+n)||!db.contracts.some(c=>c.id==='sample-contract-'+n))){if(raw)rpStore.setItem('rentpro_demo_before_repair',raw);db=rentDemo(today);}}else db=real||{rooms:[1,2,3,4].map(n=>({id:'warehouse-'+n,name:'โกดัง '+String(n).padStart(2,'0'),type:'โกดัง',rent:0})),tenants:[],contracts:[],payments:[],owner:{}};RP.migrate(db);if(demo){db._demo=true;fillDemoContracts(db,today);if(!db.rp3.invoices.some(i=>i.period===period)){let latest=db.rp3.invoices.map(i=>i.period).filter(p=>/^\d{4}-\d{2}$/.test(p)).sort().pop();if(latest)period=latest;}}else delete db._demo;base=C(db);if(!demo){let stored=rpStore.getItem('rentpro_v3_confirmed_base');if(stored){base=RP.migrate(JSON.parse(stored));knownBase=true;}}selectedRoom=db.rooms.find(r=>!r.archived)?.id||'';}catch(e){$('root').innerHTML='<div class="loading">เปิดข้อมูลไม่สำเร็จ: '+E(e.message)+'<br>ข้อมูลเดิมยังไม่ถูกลบ<br><a class="button primary" href="demo.html#properties">เปิดตัวอย่างครบ 4 หลัง</a></div>';return;}

function btn(text,action,cls='',extra=''){return '<button class="button '+cls+'" data-action="'+action+'" '+extra+'>'+text+'</button>';}
function tag(text){let k=text==='ชำระแล้ว'||text==='มีผู้เช่า'?'green':text==='ชำระบางส่วน'?'blue':text==='เกินกำหนด'?'red':text==='รอชำระ'?'amber':'';return '<span class="tag '+k+'">'+E(text)+'</span>';}
function status(i){return RP.status(db,i,today);}
function month(p){return new Date(p+'-01T00:00:00').toLocaleDateString('th-TH',{month:'long',year:'numeric'});}
function date(s){if(!s)return'—';return new Date(s.slice(0,10)+'T00:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'2-digit'});}
function panel(title,body,actions=''){return '<section class="panel"><div class="panel-head"><h2>'+title+'</h2><div class="tools">'+actions+'</div></div>'+body+'</section>';}
function field(label,name,value='',type='text',extra=''){return '<label class="field">'+label+'<input name="'+name+'" id="f-'+name+'" type="'+type+'" value="'+E(value)+'" '+(type==='number'?'step="any" ':'')+extra+'></label>';}
function area(label,name,value=''){return '<label class="field wide">'+label+'<textarea name="'+name+'">'+E(value)+'</textarea></label>';}
function dataForm(id,body){return '<form id="'+id+'" class="fields">'+body+'</form>';}
function formValues(id){let form=$(id);if(!form.reportValidity())throw Error('กรอกข้อมูลที่จำเป็นให้ครบ');return Object.fromEntries(new FormData(form));}
function tenant(id){return RP.tenantName(db,id);}
function activeRooms(){return db.rooms.filter(r=>!r.archived);}
function invoicesFor(p=period){return db.rp3.invoices.filter(i=>i.period===p&&i.state==='issued');}
function currentCycle(){return db.rp3.cycles.find(c=>c.period===period&&c.state!=='void');}
function isDirty(){return !demo&&rpStore.getItem('rentpro_v3_pending')==='1';}
function save(action,ref=''){RentModel.syncPayments(db,today);db.updatedAt=now();db.rp3.audit.push({id:uid(),at:now(),action,ref,demo});rpStore.setItem(demo?'rentpro_demo_v4':'rentpro_v2',JSON.stringify(db));if(!demo){rpStore.setItem('rentpro_v3_pending','1');clearTimeout(syncTimer);if((db.fbcfg||{}).projectId&&(db.fbcfg||{}).auto!=='off')syncTimer=setTimeout(()=>sync().catch(()=>{}),800);}renderStatus();}
function toast(text){$('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.textContent=text;document.body.appendChild(el);setTimeout(()=>el.remove(),4500);}
function message(error){toast(error.message||String(error));}
function nav(target){if(page==='billing')cacheDraft();page=target;working=null;search='';filter='all';history.replaceState(null,'','#'+page);render();window.scrollTo(0,0);}
function renderStatus(){let el=$('connection');if(el)el.innerHTML='<span class="status-dot '+(cloudReady?'online':'')+'"></span>'+(demo?(rpStore.examplePage?'ข้อมูลตัวอย่างพร้อมทดลอง':'ข้อมูลสาธิตในเครื่อง'):busy?'กำลังซิงค์ข้อมูล':cloudError?'มีข้อมูลรอซิงค์':cloudReady?(isDirty()?'มีรายการรอซิงค์':'เชื่อมต่อคลาวด์แล้ว'):'บันทึกในเครื่อง');}
function render(){if(location.hash!=='#'+page)history.replaceState(null,'','#'+page);let arrears=db.rp3.invoices.filter(i=>i.state==='issued'&&i.due&&i.due<today&&RP.balance(db,i)>0).length;let html='<aside class="side"><div class="brand"><span class="brandmark">'+icon('properties')+'</span><div><strong>RentPro<span style="font-size:9px;color:#90a3a8;margin-left:4px">4.0</span></strong><small>จัดการโกดังให้เช่า</small></div></div><div class="side-label">จัดการโครงการ</div><nav class="nav">'+Object.entries(names).map(([k,v])=>'<button data-nav="'+k+'" class="'+(page===k?'on':'')+'">'+icon(k)+v+(k==='payments'&&arrears?'<span class="counter">'+arrears+'</span>':'')+'</button>').join('')+'</nav><div class="side-bottom"><b>'+E(db.owner.building||'โกดังให้เช่าของคุณ')+'</b><small id="connection"></small><small>ค่าน้ำ–ไฟตามต้นทุนจริง<br>ไม่มีบวกเพิ่ม</small></div></aside><div class="layout"><header class="top"><span class="breadcrumb">โครงการโกดัง / '+names[page]+'</span><div class="top-right">'+(demo?'<span class="demo-pill">ข้อมูลตัวอย่าง · 4 หลัง</span>':'<span class="tag green">ข้อมูลจริง</span>')+btn(demo?'เปิดข้อมูลจริง':'ดูข้อมูลตัวอย่าง','switch-mode','small')+'<span class="avatar">'+(demo?'ตย.':'พี่')+'</span></div></header><main class="page"><div class="page-head"><div><h1>'+({overview:'ภาพรวมโกดัง',billing:'ทำบิลรายเดือน',payments:'ใบแจ้งหนี้และรับชำระ',properties:'ห้องและผู้เช่า',settings:'ตั้งค่าโครงการ'}[page])+'</h1><p>'+({overview:'มองเห็นรายรับ ยอดค้าง และสถานะทั้ง 4 หลังในหน้าเดียว',billing:'กรอกบิลหลัก จดมิเตอร์ และตรวจยอดก่อนเรียกเก็บ',payments:'ติดตามใบแจ้งหนี้ รับเงิน และออกใบเสร็จ',properties:'ข้อมูลโกดัง ผู้เช่า และสัญญาของแต่ละหลัง',settings:'ข้อมูลผู้ให้เช่า การเชื่อมต่อ และประวัติการทำรายการ'}[page])+'</p></div><div class="tools">'+(['overview','billing','payments'].includes(page)?'<input type="month" id="period" aria-label="เดือนที่จัดการ" value="'+period+'">':'')+(page==='overview'?btn(icon('billing')+'ทำบิลรายเดือน','go-billing','primary'):'')+(page==='properties'?btn('+ เพิ่มโกดัง','add-room','primary'):'')+'</div></div>'+(demo?'<div class="demo-banner"><span><b>โหมดสาธิต</b> · ทดลองแก้ไข รับเงิน และออกบิลได้ ข้อมูลชุดนี้แยกจากข้อมูลจริง</span>'+btn('เริ่มตัวอย่างใหม่','reset-demo','small')+'</div>':!cloudReady?'<div class="notice '+(cloudError?'error':'warn')+'">'+E(cloudError||'ข้อมูลกำลังบันทึกในเครื่องนี้ ตรวจการเชื่อมต่อคลาวด์ก่อนใช้หลายเครื่อง')+' '+btn('ตั้งค่าการเชื่อมต่อ','go-cloud','link')+'</div>':'')+(!demo&&!db.contracts.length?'<div class="notice warn"><b>ข้อมูลจริงยังไม่มีสัญญาเช่า</b> · ข้อมูลตัวอย่างอยู่คนละชุด <a class="button primary small" href="demo.html#properties">เปิดตัวอย่างครบ 4 หลัง</a></div>':'')+({overview,billing,payments,properties,settings}[page])()+'<div class="subtle-footer">RentPro 4.0 · '+(demo?'ข้อมูลทั้งหมดในโหมดนี้เป็นข้อมูลสมมติ':'เก็บวิธีคำนวณและประวัติไว้กับแต่ละบิล')+'</div></main></div>'; $('root').innerHTML=html;renderStatus();}
function metric(label,amount,sub,which='payments',good=false){return '<div class="metric"><div class="metric-top"><span>'+label+'</span><span class="metric-icon">'+icon(which)+'</span></div><strong>'+amount+'</strong><small class="'+(good?'good':'')+'">'+sub+'</small></div>';}
function invoiceTable(list,compact=false){if(!list.length)return '<div class="empty">ไม่มีรายการในช่วงที่เลือก<br>เริ่มจากทำบิลรายเดือน หรือเปลี่ยนเดือนที่ต้องการดู</div>';return '<div class="table-wrap"><table><thead><tr><th>ห้อง / เลขที่บิล</th><th>ผู้เช่า</th>'+(!compact?'<th class="num">ค่าเช่า</th><th class="num">น้ำ + ไฟ</th>':'')+'<th class="num">คงเหลือ</th><th>สถานะ</th><th></th></tr></thead><tbody>'+list.map(i=>'<tr><td><b>'+E(i.roomName)+'</b><small>'+E(i.number)+' · '+date(i.due)+'</small></td><td>'+E(i.tenantName)+'</td>'+(!compact?'<td class="num">'+M(i.rent)+'</td><td class="num">'+M(i.water+i.electric)+'</td>':'')+'<td class="num"><b class="'+(status(i)==='เกินกำหนด'?'money-red':'')+'">'+M(i.state==='void'?0:RP.balance(db,i))+'</b></td><td>'+tag(status(i))+'</td><td><div class="tools">'+btn('ดูบิล','detail','small','data-id="'+i.id+'"')+(i.state==='issued'&&RP.balance(db,i)>0?btn('รับเงิน','receive','primary small','data-id="'+i.id+'"'):'')+'</div></td></tr>').join('')+'</tbody></table></div>';}
function overview(){let current=invoicesFor(),all=db.rp3.invoices.filter(i=>i.state==='issued'),received=db.rp3.receipts.filter(r=>!r.voided&&r.date?.startsWith(period)).reduce((s,r)=>s+r.amount,0),outstanding=all.reduce((s,i)=>s+Math.max(0,RP.balance(db,i)),0),late=all.filter(i=>i.due<today&&RP.balance(db,i)>0),rooms=activeRooms(),occupied=rooms.filter(r=>RentModel.contracts(db,r.id,period).length).length,cycle=currentCycle();return '<div class="metrics">'+metric('รับชำระแล้วเดือนนี้','฿'+M(received),'ตามวันที่รับเงินจริง','payments',true)+metric('ยอดค้างชำระทั้งหมด','฿'+M(outstanding),'เกินกำหนด '+late.length+' ใบแจ้งหนี้','clock')+metric('ค่าเช่าที่เรียกเก็บ','฿'+M(current.reduce((s,i)=>s+i.rent,0)),'เฉพาะรอบ '+month(period),'billing')+metric('โกดังมีผู้เช่า',occupied+' / '+rooms.length,'พื้นที่เช่าทั้งหมด '+rooms.reduce((s,r)=>s+Number(r.size||0),0)+' ตร.ม.','properties',true)+'</div><div class="section-title"><h2>โกดังของคุณ</h2><small>'+month(period)+'</small></div><div class="room-grid">'+rooms.map(r=>{let cs=RentModel.contracts(db,r.id,period),is=current.filter(i=>i.roomId===r.id),i=is[0],balance=is.reduce((s,x)=>s+RP.balance(db,x),0);return '<article class="room-card" tabindex="0" role="button" aria-label="ดู '+E(r.name)+'" data-room="'+r.id+'"><div class="room-top"><span class="room-icon">'+icon('properties')+'</span>'+tag(cs.length?'มีผู้เช่า':'ว่าง')+'</div><h3>'+E(r.name)+'</h3><div class="tenant">'+E(cs.length?tenant(cs[0].tenantId):'พร้อมให้เช่า')+'</div><span class="amount">฿'+M(i?i.total:(cs[0]?.rent||r.rent||0))+'</span><span class="muted" style="font-size:10px">'+(i?'ยอดเรียกเก็บเดือนนี้':'ค่าเช่าต่อเดือน')+'</span><div class="row-pair">'+(i?tag(status(i)):'<span>ยังไม่ได้ออกบิล</span>')+'<span>'+(balance>0?'คงเหลือ '+M(balance):Number(r.size||0)+' ตร.ม.')+'</span></div></article>';}).join('')+'</div><div class="split"><div>'+panel('รายการเรียกเก็บ · '+month(period),invoiceTable(current,true),btn('ดูทั้งหมด','go-payments','link'))+'</div><div>'+panel('งานที่ต้องดูแล','<div class="task"><span class="circle">'+icon(cycle?.state==='issued'?'check':'billing')+'</span><div><b>'+(cycle?.state==='issued'?'ออกบิลรอบนี้แล้ว '+current.length+' หลัง':'เตรียมบิลรอบ '+month(period))+'</b><p>'+(cycle?.state==='issued'?'บันทึกมิเตอร์และต้นทุนไว้กับบิลแล้ว':'ใส่บิลน้ำ–ไฟหลัก แล้วจดมิเตอร์ย่อยให้ครบ')+'</p></div>'+btn('เปิดดู','go-billing','small')+'</div><div class="task"><span class="circle">'+icon('clock')+'</span><div><b>ใบแจ้งหนี้เกินกำหนด '+late.length+' ใบ</b><p>ยอดที่ต้องติดตาม '+M(late.reduce((s,i)=>s+RP.balance(db,i),0))+' บาท</p></div>'+btn('ติดตาม','show-overdue','small')+'</div><div class="task"><span class="circle">'+icon('properties')+'</span><div style="width:100%"><b>อัตราการเช่า '+(rooms.length?Math.round(occupied/rooms.length*100):0)+'%</b><div class="progress-line"><span style="width:'+(rooms.length?occupied/rooms.length*100:0)+'%"></span></div><p>มีผู้เช่า '+occupied+' หลัง · ว่าง '+(rooms.length-occupied)+' หลัง</p></div></div>')+'</div></div>';}
function emptyBill(){return {units:'',usage:'',service:0,ft:0,tax:0,discount:0,billAmount:'',from:'',to:'',reference:'',attachment:null};}
function getWorking(){if(working&&working.period===period)return working;let c=currentCycle();let cached=rpStore.getItem((demo?'rentpro_demo_draft_':'rentpro_draft_')+period);working=C(c||{id:uid(),period,state:'draft',due:'',note:'',water:emptyBill(),electric:emptyBill(),rows:activeRooms().map(r=>{let prev=db.rp3.cycles.filter(x=>x.state==='issued'&&x.period<period&&x.rows.some(y=>y.roomId===r.id)).sort((a,b)=>b.period.localeCompare(a.period))[0]?.rows.find(x=>x.roomId===r.id);return {roomId:r.id,waterPrev:prev?.waterNow??'',waterNow:'',electricPrev:prev?.electricNow??'',electricNow:''};})});if(c?.state!=='issued'&&cached){try{working=JSON.parse(cached);}catch{}}return working;}
function cacheDraft(){if(working&&working.state==='draft')rpStore.setItem((demo?'rentpro_demo_draft_':'rentpro_draft_')+period,JSON.stringify(working));}
function billForm(k,title){let c=getWorking(),b=c[k],disabled=c.state==='issued'?'disabled':'';return panel(icon(k)+' '+title,'<div class="panel-body"><div class="fields">'+field('รอบบิลเริ่มวันที่',k+'-from',b.from,'date',disabled)+field('รอบบิลสิ้นสุดวันที่',k+'-to',b.to,'date',disabled)+field('หน่วยใช้ในบิลหลัก',k+'-units',b.units,'number',disabled+' min="0"')+field(k==='electric'?'ค่าพลังงานไฟฟ้า (ไม่รวม Ft)':'ค่าน้ำตามบิล (บาท)',k+'-usage',b.usage,'number',disabled+' min="0"')+field('ค่าบริการ (บาท)',k+'-service',b.service,'number',disabled+' min="0"')+(k==='electric'?field('ค่า Ft ตามบิล (บาท)',k+'-ft',b.ft??0,'number',disabled):'')+field('VAT ตามบิล (บาท)',k+'-tax',b.tax,'number',disabled+' min="0"')+field('ส่วนลดตามบิล (บาท)',k+'-discount',b.discount??0,'number',disabled+' min="0"')+field('ยอดรวมเดือนปัจจุบัน (ตรวจยอด)',k+'-billAmount',b.billAmount??'','number',disabled+' min="0"')+field('เลขอ้างอิงบิล',k+'-reference',b.reference,'text',disabled)+'<label class="field wide">ภาพบิลหลัก · ไม่เกิน 5 MB<input type="file" accept="image/png,image/jpeg,image/webp" data-file="'+k+'" '+disabled+'></label></div>'+(b.attachment?'<div class="image-label">'+icon('check')+E(b.attachment.name)+' '+btn('ดูภาพ','view-bill','link','data-kind="'+k+'"')+'</div>':'')+'</div><div class="bill-total"><span>รวมต้นทุนรอบนี้</span><b id="total-'+k+'">฿'+M(billSum(b))+'</b></div>');}
function billSum(b){return RP.money(Number(b.usage||0)+Number(b.service||0)+Number(b.ft||0)+Number(b.tax||0)-Number(b.discount||0));}
function calcPanel(cal){return '<div class="two">'+['water','electric'].map(k=>panel('ต้นทุน'+(k==='water'?'น้ำ':'ไฟ')+'ที่จัดสรร','<div class="panel-body"><div class="details-grid"><div><span class="key">ต้นทุนต่อหน่วย</span><b>'+cal[k].rate.toFixed(6)+' บาท</b></div><div><span class="key">หน่วยส่วนต่าง</span><b>'+Number(cal[k].differenceUnits.toFixed(6))+' หน่วย</b></div><div><span class="key">ต้นทุนห้องว่าง</span><b>'+M(cal[k].vacantAmount||0)+' บาท</b></div><div><span class="key">เจ้าของรับผิดชอบรวม</span><b>'+M(cal[k].ownerTotal)+' บาท</b></div></div><div class="bill-balance">รวมเศษปัดทศนิยม '+M(cal[k].rounding)+' บาท</div></div>')).join('')+'</div>';}
function billing(){let c=getWorking(),locked=c.state==='issued';let body='<div class="steps">'+[[1,'บิลหลัก'],[2,'มิเตอร์ย่อย'],[3,'ตรวจและออกบิล']].map(([n,title])=>'<button data-stage="'+n+'" class="'+(stage===n?'on':'')+'"><span>'+n+'</span>'+title+'</button>').join('')+'</div>'+(locked?'<div class="notice">'+tag('ออกบิลแล้ว')+' รอบนี้ล็อกยอดมิเตอร์และสูตรไว้เรียบร้อย '+btn('ดูใบแจ้งหนี้','go-payments','link')+'</div>':'');if(stage===1)body+='<div class="two">'+billForm('water','บิลค่าน้ำหลัก')+billForm('electric','บิลค่าไฟหลัก')+'</div><div class="notice">นำเฉพาะค่าใช้จ่ายเดือนปัจจุบันมาจัดสรร ไม่รวมยอดค้างเก่า ค่าปรับ และเงินประกัน · กรอกภาษีตามบิล ไม่คำนวณซ้ำ</div>';if(stage===2){body+=panel('จดมิเตอร์ย่อย · '+c.rows.length+' หลัง','<div class="table-wrap"><table class="meter-table"><thead><tr><th rowspan="2">โกดัง / ผู้เช่า</th><th colspan="3" class="group">ค่าน้ำ</th><th colspan="3" class="group electric">ค่าไฟ</th></tr><tr><th>ครั้งก่อน</th><th>ครั้งนี้</th><th>หน่วยใช้</th><th>ครั้งก่อน</th><th>ครั้งนี้</th><th>หน่วยใช้</th></tr></thead><tbody>'+c.rows.map(r=>{let room=db.rooms.find(x=>x.id===r.roomId),cs=RentModel.contracts(db,r.roomId,period);return '<tr><td><b>'+E(room?.name||'โกดังเดิม')+'</b><small>'+E(cs.length?tenant(cs[0].tenantId):'ไม่มีผู้เช่า · เจ้าของรับผิดชอบ')+'</small></td>'+['water','electric'].map(k=>['Prev','Now'].map(part=>'<td><input class="meter-input" aria-label="'+E(room?.name)+' '+k+part+'" type="number" min="0" step="any" data-read="'+k+part+'" data-roomid="'+r.roomId+'" value="'+E(r[k+part])+'" '+(locked?'disabled':'')+'></td>').join('')+'<td class="num" id="use-'+k+'-'+r.roomId+'">'+(r[k+'Now']!==''&&r[k+'Prev']!==''?Number((Number(r[k+'Now'])-Number(r[k+'Prev'])).toFixed(6)):'—')+'</td>').join('')+'</tr>';}).join('')+'</tbody></table></div>')+'<div class="notice warn">จดมิเตอร์ให้ตรงกับช่วงบิลหลัก · หากผลรวมหน่วยย่อยเกินหน่วยหลัก ระบบจะไม่ให้ออกบิล · ส่วนต่างและหน่วยของห้องว่างเป็นต้นทุนเจ้าของ</div>';}if(stage===3){try{let cal=RentModel.calculate(db,c),list=locked?invoicesFor():RentModel.build(db,c,uid,now()).invoices;body+=panel('ตรวจยอดก่อนออกใบแจ้งหนี้','<div class="table-wrap"><table><thead><tr><th>โกดัง / ผู้เช่า</th><th class="num">ค่าเช่า</th><th class="num">ค่าน้ำ</th><th class="num">ค่าไฟ</th><th class="num">รวมเรียกเก็บ</th></tr></thead><tbody>'+list.map(i=>'<tr><td><b>'+E(i.roomName)+'</b><small>'+E(i.tenantName)+'</small></td><td class="num">'+M(i.rent)+'</td><td class="num">'+M(i.water)+'</td><td class="num">'+M(i.electric)+'</td><td class="num"><b>'+M(i.total)+'</b></td></tr>').join('')+'</tbody></table></div><div class="bill-total"><span>รวม '+list.length+' ใบแจ้งหนี้</span><b>฿'+M(list.reduce((s,i)=>s+i.total,0))+'</b></div>')+calcPanel(cal);if(!locked)body+=panel('กำหนดเรียกเก็บ','<div class="panel-body"><div class="fields">'+field('กำหนดชำระร่วม (เว้นว่างใช้วันในสัญญา)','due',c.due,'date')+field('หมายเหตุในใบแจ้งหนี้','note',c.note)+'</div></div>');}catch(e){body+='<div class="notice warn">'+E(e.message)+' '+btn('กลับไปบิลหลัก','stage-one','link')+'</div>';}}return body+'<div class="tools" style="justify-content:space-between"><div class="tools">'+(!locked?btn('บันทึกร่าง','save-draft'):'')+(stage>1?btn('← ย้อนกลับ','stage-prev'):'')+'</div><div class="tools">'+(locked?btn('ดูบิลและรับชำระ','go-payments','primary')+(stage===3?btn('ยกเลิกรอบบิล','cancel-cycle','danger'):''):stage<3?btn('ถัดไป '+icon('arrow'),'stage-next','primary'):btn('ยืนยันออกใบแจ้งหนี้','issue-preview','primary'))+'</div></div>';}
function payments(){let list=db.rp3.invoices.filter(i=>(allPeriods||i.period===period)&&(filter==='all'||filter==='unpaid'&&i.state==='issued'&&RP.balance(db,i)>0||filter==='paid'&&status(i)==='ชำระแล้ว'||filter==='overdue'&&status(i)==='เกินกำหนด'));if(search)list=list.filter(i=>(i.number+' '+i.roomName+' '+i.tenantName).toLowerCase().includes(search.toLowerCase()));return '<div class="tabs">'+[['all','ทั้งหมด'],['unpaid','ค้างชำระ'],['paid','ชำระแล้ว'],['overdue','เกินกำหนด']].map(([key,label])=>'<button data-filter="'+key+'" class="'+(filter===key?'on':'')+'">'+label+'</button>').join('')+'</div>'+panel('ใบแจ้งหนี้ '+(allPeriods?'ทุกเดือน':month(period)),invoiceTable(list),'<input id="search" class="search" type="search" aria-label="ค้นหาใบแจ้งหนี้" placeholder="ค้นหาห้อง ผู้เช่า เลขที่บิล" value="'+E(search)+'"><label class="muted" style="display:flex;gap:7px;align-items:center;white-space:nowrap;font-size:10px"><input id="all-periods" type="checkbox" style="width:auto" '+(allPeriods?'checked':'')+'>ทุกเดือน</label>'+btn('ส่งออก','csv','small'));}
function properties(){let rooms=activeRooms(),r=rooms.find(r=>r.id===selectedRoom)||rooms[0];if(!r)return '<div class="empty">ยังไม่มีโกดัง '+btn('+ เพิ่มโกดัง','add-room','primary')+'</div>';selectedRoom=r.id;let cs=db.contracts.filter(c=>c.roomId===r.id&&!c.archived).sort((a,b)=>b.startDate.localeCompare(a.startDate)),c=cs.find(c=>c.startDate<=today&&c.endDate>=today)||cs[0],t=c&&db.tenants.find(t=>t.id===c.tenantId);let keyValue=(key,v)=>'<div><span class="key">'+key+'</span><div class="value">'+E(v||'—')+'</div></div>';return '<div class="property-layout"><div class="room-list">'+rooms.map(room=>'<button data-room="'+room.id+'" class="'+(room.id===r.id?'on':'')+'"><div class="label"><strong>'+E(room.name)+'</strong>'+tag(RentModel.contracts(db,room.id,period).length?'มีผู้เช่า':'ว่าง')+'</div><small>'+Number(room.size||0)+' ตร.ม. · ค่าเช่า '+M(room.rent)+'</small></button>').join('')+'</div><div><div class="property-top"><div><h2>'+E(r.name)+'</h2><span class="muted">'+E(r.desc||'ข้อมูลโกดังและประวัติผู้เช่า')+'</span></div><div class="tools">'+btn('แก้ไขโกดัง','edit-room','','data-id="'+r.id+'"')+btn('ปิดใช้งาน','archive-room','danger small','data-id="'+r.id+'"')+'</div></div>'+panel('ข้อมูลโกดัง','<div class="panel-body"><div class="details-grid">'+keyValue('พื้นที่',Number(r.size||0)+' ตร.ม.')+keyValue('ค่าเช่าพื้นฐาน',M(r.rent)+' บาท / เดือน')+keyValue('รายละเอียด',r.facilities)+keyValue('ตำแหน่ง',r.floor)+'</div></div>')+panel('ผู้เช่าและสัญญา','<div class="panel-body">'+(t?'<div class="details-grid">'+keyValue('ผู้เช่า',tenant(t.id))+keyValue('เบอร์ติดต่อ',t.phone)+keyValue('อีเมล',t.email)+keyValue('ที่อยู่',t.address)+keyValue('เลขที่สัญญา',c.number||c.id)+keyValue('วันทำสัญญา',date(c.signedDate||c.startDate))+keyValue('ช่วงสัญญา',date(c.startDate)+' – '+date(c.endDate))+keyValue('ค่าเช่าตามสัญญา',M(c.rent)+' บาท / เดือน')+keyValue('เงินประกัน',M(c.deposit)+' บาท')+keyValue('กำหนดชำระ','วันที่ '+(c.dueDay||1)+' ของเดือน')+keyValue('วัตถุประสงค์การเช่า',c.permittedUse||c.purpose)+keyValue('ผู้ประสานงาน',c.tenantContact||t.contactPerson)+keyValue('มิเตอร์น้ำ / ไฟ',((c.waterMeterNo||'—')+' / '+(c.electricMeterNo||'—')))+'</div><div class="tools" style="margin-top:20px">'+btn('แก้ไขผู้เช่า','edit-tenant','','data-id="'+t.id+'"')+btn('แก้ไขสัญญา','edit-contract','','data-id="'+c.id+'"')+btn('ดูสัญญา','view-contract','','data-id="'+c.id+'"')+btn('ยุติสัญญา','end-contract','danger small','data-id="'+c.id+'"')+'</div>':'<div class="empty">ยังไม่มีสัญญาสำหรับโกดังหลังนี้<br>'+btn('เพิ่มผู้เช่าและสัญญา','new-contract','primary','data-id="'+r.id+'"')+'</div>')+'</div>')+panel('ประวัติสัญญา','<div class="table-wrap"><table><thead><tr><th>ผู้เช่า</th><th>ระยะเวลา</th><th>สถานะ</th><th></th></tr></thead><tbody>'+db.contracts.filter(x=>x.roomId===r.id).map(x=>'<tr><td>'+E(tenant(x.tenantId))+'</td><td>'+date(x.startDate)+' – '+date(x.endDate)+'</td><td>'+tag(x.archived?'ยุติแล้ว':x.startDate>today?'รอเริ่ม':x.endDate<today?'หมดอายุ':'ใช้งาน')+'</td><td>'+btn('ดูสัญญา','view-contract','small','data-id="'+x.id+'"')+'</td></tr>').join('')+'</tbody></table></div>')+panel('ประวัติใบแจ้งหนี้ของหลังนี้',invoiceTable(db.rp3.invoices.filter(i=>i.roomId===r.id),true))+'</div></div>';}
function settings(){let o=db.owner,cfg=db.fbcfg||{};let tabs='<div class="tabs">'+[['owner','ผู้ให้เช่าและรับเงิน'],['cloud','การเชื่อมต่อข้อมูล'],['backup','สำรองและประวัติ']].map(([k,v])=>'<button data-setting="'+k+'" class="'+(settingsTab===k?'on':'')+'">'+v+'</button>').join('')+'</div>';if(settingsTab==='owner')return tabs+panel('ข้อมูลที่แสดงในใบแจ้งหนี้และใบเสร็จ','<div class="panel-body">'+dataForm('owner-form',field('ชื่อผู้ให้เช่า / นิติบุคคล','name',o.name,'text','required')+field('ชื่อโครงการ','building',o.building)+field('เบอร์โทรศัพท์','phone',o.phone)+field('อีเมล','email',o.email,'email')+area('ที่อยู่ผู้ให้เช่า','address',o.address)+area('ที่ตั้งโครงการ','propertyAddr',o.propertyAddr)+area('บัญชีรับชำระ','bank',o.bank))+'<div class="tools" style="margin-top:20px">'+btn('บันทึกข้อมูล','save-owner','primary')+'</div><p class="muted" style="font-size:10px;margin-top:15px">การแก้ไขข้อมูลผู้ให้เช่าใช้กับบิลใหม่ บิลที่ออกแล้วเก็บข้อมูลเดิมไว้</p></div>');if(settingsTab==='cloud')return tabs+panel('คลาวด์กลางของโครงการ','<div class="panel-body">'+(demo?'<div class="notice warn">โหมดตัวอย่างไม่เชื่อมต่อคลาวด์ และไม่ส่งข้อมูลสาธิตเข้าฐานข้อมูลจริง '+btn('เปิดข้อมูลจริงเพื่อตั้งค่า','switch-mode','link')+'</div>':'<div class="notice '+(cloudError?'error':'')+'">'+E(cloudError||'แยกเก็บข้อมูลเป็นรายห้อง รายบิล และรายรับชำระ พร้อมตรวจการแก้พร้อมกันก่อนบันทึก')+'</div>')+dataForm('cloud-form',field('Firebase Project ID','projectId',cfg.projectId)+field('Firebase API Key','apiKey',cfg.apiKey)+field('Firebase Auth Domain','authDomain',cfg.authDomain)+'<label class="field">การซิงค์<select name="auto"><option value="on" '+(cfg.auto!=='off'?'selected':'')+'>ซิงค์เมื่อบันทึก</option><option value="off" '+(cfg.auto==='off'?'selected':'')+'>ซิงค์ด้วยตนเอง</option></select></label>')+'<div class="tools" style="margin-top:20px">'+btn('บันทึกการเชื่อมต่อ','save-cloud','primary',demo?'disabled':'')+btn('ซิงค์และตรวจการเชื่อมต่อ','sync','',demo?'disabled':'')+btn('โหลดจากคลาวด์','pull-cloud','',demo?'disabled':'')+'</div><p class="muted" style="font-size:11px;line-height:1.9">ใช้การตั้งค่า Firebase เดิมของโครงการ ข้อมูลจากระบบเก่าจะถูกเก็บสำรองก่อนย้าย<br>Google Sheets เดิมไม่ซิงค์อัตโนมัติ เพื่อไม่ให้ข้อมูลสองแหล่งทับกัน</p></div>');return tabs+panel('สำรองข้อมูลของโหมด'+(demo?'ตัวอย่าง':'จริง'),'<div class="panel-body"><div class="tools">'+btn('ดาวน์โหลดข้อมูลปัจจุบัน','export','primary')+btn('ข้อมูลก่อนปรับรุ่น 4.0','export-old','',demo?'disabled':'')+'<label class="button">นำเข้าไฟล์สำรอง<input id="import" type="file" accept=".json,application/json" hidden></label></div><p class="muted" style="font-size:11px;line-height:1.9">ไฟล์สำรองมีข้อมูลผู้เช่าและการตั้งค่าการเชื่อมต่อ ควรเก็บไว้เป็นส่วนตัว<br>นำเข้าเฉพาะโหมดที่กำลังเปิด และตรวจรายการที่ขัดกันก่อนรวม</p></div>')+panel('ประวัติการทำรายการ','<div class="table-wrap"><table><thead><tr><th>วัน / เวลา</th><th>รายการ</th><th>อ้างอิง</th></tr></thead><tbody>'+db.rp3.audit.slice().reverse().slice(0,100).map(a=>'<tr><td>'+E(new Date(a.at).toLocaleString('th-TH'))+'</td><td>'+E(a.action)+'</td><td class="muted">'+E(a.ref||'—')+'</td></tr>').join('')+'</tbody></table></div>');}
function modal(title,body,footer='',wide=false){close();let el=document.createElement('div');el.className='modal-backdrop';el.id='modal';el.innerHTML='<section class="modal '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="'+E(title)+'"><div class="modal-header"><h2>'+title+'</h2><button class="close" data-action="close" aria-label="ปิดหน้าต่าง">×</button></div><div class="modal-body">'+body+'</div>'+(footer?'<div class="modal-footer">'+footer+'</div>':'')+'</section>';document.body.appendChild(el);el.querySelector('input,select,button')?.focus();}
function close(){ $('modal')?.remove();modalData={};}
function detail(id){let i=db.rp3.invoices.find(x=>x.id===id);if(!i)return;let receipts=db.rp3.receipts.filter(r=>r.invoiceId===id);let text='<div class="property-top"><div><h2>'+E(i.roomName)+'</h2><span class="muted">'+E(i.tenantName)+' · '+month(i.period)+'</span></div>'+tag(status(i))+'</div><div class="details-grid"><div><span class="key">เลขที่ใบแจ้งหนี้</span><b>'+E(i.number)+'</b></div><div><span class="key">กำหนดชำระ</span><b>'+date(i.due)+'</b></div></div><table style="margin-top:20px"><thead><tr><th>รายการ</th><th class="num">จำนวนเงิน</th></tr></thead><tbody>'+[['ค่าเช่า',i.rent],['ค่าน้ำ',i.water],['ค่าไฟ',i.electric],['อื่น ๆ',i.other]].filter(x=>x[1]||x[0]==='ค่าเช่า').map(([label,v])=>'<tr><td>'+label+'</td><td class="num">'+M(v)+'</td></tr>').join('')+'</tbody></table><div class="invoice-total"><span>ยอดรวม '+M(i.total)+' บาท<br><small class="muted">ยอดคงเหลือ</small></span><strong>฿'+M(i.state==='void'?0:RP.balance(db,i))+'</strong></div>'+(i.snapshot?'<div class="two">'+['water','electric'].map(k=>{let s=i.snapshot[k];return '<div class="notice" style="font-size:11px">'+(k==='water'?'น้ำ':'ไฟ')+' · มิเตอร์ '+s.previous+' → '+s.current+'<br>'+s.units+' หน่วย × '+s.rate.toFixed(6)+' บาท<br><span class="muted" style="font-size:10px">รอบหลัก '+date(s.bill.from)+' – '+date(s.bill.to)+'</span></div>';}).join('')+'</div>':'<p class="muted">บิลจากระบบเดิม ไม่มีประวัติเลขมิเตอร์แนบ</p>')+'<h3 style="font-size:13px">ประวัติรับชำระ</h3>'+(receipts.length?'<div class="timeline">'+receipts.map(r=>'<div><b>'+date(r.date)+' · '+M(r.amount)+' บาท</b> '+(r.voided?tag('ยกเลิกแล้ว'):'')+'<small>'+E(r.method)+' · '+E(r.note||'ไม่มีหมายเหตุ')+'</small><div class="tools" style="margin-top:7px;padding-bottom:0">'+(!r.voided?btn('ใบเสร็จ','print-receipt','small','data-id="'+r.id+'"')+btn('ยกเลิกการรับ','void-receipt','link','data-id="'+r.id+'"'):'')+(r.proof?btn('ดูหลักฐาน','view-proof','link','data-id="'+r.id+'"'):'')+'</div></div>').join('')+'</div>':'<p class="muted">ยังไม่มีรายการรับเงิน</p>')+(i.note?'<p class="muted">หมายเหตุ: '+E(i.note)+'</p>':'')+(i.state==='void'?'<div class="notice warn">ยกเลิกแล้ว: '+E(i.voidReason)+'</div>':'');modal('รายละเอียดใบแจ้งหนี้',text,btn('พิมพ์ใบแจ้งหนี้','print-invoice','','data-id="'+id+'"')+(i.state==='issued'&&RP.balance(db,i)>0?btn('รับชำระ','receive','primary','data-id="'+id+'"'):'')+(i.state==='issued'?btn('ยกเลิกบิล','void-invoice','danger','data-id="'+id+'"'):''),true);}
function receiveModal(id){let i=db.rp3.invoices.find(x=>x.id===id);if(!i||i.state!=='issued'||RP.balance(db,i)<=0)throw Error('ใบแจ้งหนี้นี้ไม่มีเงินค้างรับ');modal('รับชำระ · '+E(i.roomName),'<div class="notice">'+E(i.tenantName)+' · '+E(i.number)+'<br>ยอดคงเหลือ <b>'+M(RP.balance(db,i))+' บาท</b></div>'+dataForm('receive-form',field('จำนวนเงินที่รับ (บาท)','amount',RP.balance(db,i),'number','min="0.01" required')+field('วันที่รับเงินจริง','date',today,'date','max="'+today+'" required')+'<label class="field">ช่องทางชำระ<select name="method"><option>โอนเงิน</option><option>เงินสด</option><option>อื่น ๆ</option></select></label>'+field('เลขอ้างอิง / หมายเหตุ','note')+'<label class="field wide">แนบหลักฐานการชำระ · ไม่เกิน 5 MB<input type="file" data-file="proof" accept="image/png,image/jpeg,image/webp"></label>')+'<div id="proof-name" class="image-label"></div>',btn('ยกเลิก','close')+btn('บันทึกรับเงิน','save-receipt','primary','data-id="'+id+'"'));}
function roomModal(id){let r=db.rooms.find(r=>r.id===id)||{};modal(id?'แก้ไข '+E(r.name):'เพิ่มโกดัง',dataForm('room-form',field('ชื่อโกดัง','name',r.name,'text','required')+field('พื้นที่ (ตร.ม.)','size',r.size||0,'number','min="0"')+field('ค่าเช่าพื้นฐาน (บาท)','rent',r.rent||0,'number','min="0" required')+field('ตำแหน่ง / ชั้น','floor',r.floor)+area('รายละเอียด / สิ่งอำนวยความสะดวก','facilities',r.facilities)+area('หมายเหตุ','desc',r.desc)),btn('ยกเลิก','close')+btn('บันทึกโกดัง','save-room','primary','data-id="'+(id||'')+'"'));}
function tenantModal(id){let t=db.tenants.find(t=>t.id===id)||{};modal('แก้ไขข้อมูลผู้เช่า',dataForm('tenant-form',field('ชื่อบุคคล / ชื่อกิจการ','fname',t.fname,'text','required')+field('นามสกุล (ถ้ามี)','lname',t.lname)+field('คำนำหน้า','prefix',t.prefix)+field('เบอร์โทรศัพท์','phone',t.phone)+field('อีเมล','email',t.email,'email')+field('LINE / ช่องทางติดต่อ','line',t.line)+area('ที่อยู่','address',t.address)),btn('ยกเลิก','close')+btn('บันทึกผู้เช่า','save-tenant','primary','data-id="'+id+'"'));}
function contractModal(id,roomId){let c=db.contracts.find(c=>c.id===id)||{},newTenant=!id;let tenantOptions=db.tenants.filter(t=>!t.archived).map(t=>'<option value="'+t.id+'" '+(c.tenantId===t.id?'selected':'')+'>'+E(tenant(t.id))+'</option>').join('');let r=db.rooms.find(r=>r.id===(c.roomId||roomId));modal(id?'แก้ไขสัญญา · '+E(r?.name):'ผู้เช่าและสัญญา · '+E(r?.name),dataForm('contract-form',(newTenant?'<label class="field wide">ผู้เช่า<select name="tenantId"><option value="new">เพิ่มผู้เช่าใหม่</option>'+tenantOptions+'</select></label>'+field('ชื่อผู้เช่าหรือกิจการใหม่','newName','','text')+field('เบอร์โทรศัพท์','newPhone'):'<label class="field wide">ผู้เช่า<select name="tenantId">'+tenantOptions+'</select></label>')+field('เลขที่สัญญา','number',c.number||'')+field('วันทำสัญญา','signedDate',c.signedDate||c.startDate||today,'date')+field('วันเริ่มสัญญา','startDate',c.startDate||today,'date','required')+field('วันสิ้นสุดสัญญา','endDate',c.endDate||'','date','required')+field('ค่าเช่าตามสัญญา (บาท)','rent',c.rent??r?.rent??0,'number','min="0" required')+field('เงินประกัน (บาท)','deposit',c.deposit||0,'number','min="0"')+field('ค่าเช่าล่วงหน้า (บาท)','advance',c.advance||0,'number','min="0"')+field('กำหนดชำระวันที่','dueDay',c.dueDay||10,'number','min="1" max="31" step="1" required')+field('วันส่งมอบพื้นที่','handoverDate',c.handoverDate||c.startDate||today,'date')+field('ผู้ประสานงานฝ่ายผู้เช่า','tenantContact',c.tenantContact||'')+field('วัตถุประสงค์การเช่า','permittedUse',c.permittedUse||c.purpose||'เพื่อประกอบธุรกิจ')+field('ผู้ประสานงานฝ่ายผู้ให้เช่า','ownerContact',c.ownerContact||'')+field('เลขมิเตอร์น้ำ','waterMeterNo',c.waterMeterNo||'')+field('เลขมิเตอร์ไฟ','electricMeterNo',c.electricMeterNo||'')+area('เงื่อนไข / หมายเหตุสัญญา','terms',c.terms))+'<p class="muted" style="font-size:10px">ค่าน้ำ–ค่าไฟของรอบใหม่คิดตามทุนบิลจริง · บิลที่ออกแล้วไม่เปลี่ยนตามการแก้สัญญา</p>',btn('ยกเลิก','close')+btn('บันทึกสัญญา','save-contract','primary','data-id="'+(id||'')+'" data-roomid="'+(c.roomId||roomId)+'"'),true);}
function reasonModal(title,action,id,text){modal(title,'<div class="notice warn">'+E(text)+'</div>'+dataForm('reason-form',area('เหตุผล (จำเป็น)','reason','')),btn('ย้อนกลับ','close')+btn('ยืนยัน','confirm-'+action,'danger','data-id="'+id+'"'));}
function imageModal(image){if(!image||!/^data:image\/(png|jpeg|webp);base64,/.test(image.data))throw Error('ไม่พบภาพที่เปิดได้');modal('ภาพแนบ · '+E(image.name),'<img class="image-preview" alt="ภาพบิลหรือหลักฐานที่แนบ" src="'+E(image.data)+'">',btn('ปิด','close'),true);}
function draftSave(){let c=getWorking(),idx=db.rp3.cycles.findIndex(x=>x.id===c.id);if(idx>=0)db.rp3.cycles[idx]=C(c);else db.rp3.cycles.push(C(c));cacheDraft();save('บันทึกร่างบิลรายเดือน',c.id);toast('บันทึกร่างแล้ว');}
function issuePreview(){let c=getWorking(),built=RentModel.build(db,c,uid,now());modal('ยืนยันออกใบแจ้งหนี้','<div class="notice">รอบ '+month(period)+' · '+built.invoices.length+' หลัง<br>รวมเรียกเก็บ <b>'+M(built.invoices.reduce((s,i)=>s+i.total,0))+' บาท</b><br>หลังยืนยัน ระบบจะล็อกยอดมิเตอร์และวิธีคำนวณของรอบนี้</div>',btn('กลับไปตรวจ','close')+btn('ออกใบแจ้งหนี้','confirm-issue','primary'));}
function printDocument(invoiceId,receiptId){let i=db.rp3.invoices.find(i=>i.id===invoiceId),r=receiptId&&db.rp3.receipts.find(r=>r.id===receiptId);if(!i||r?.voided)return;let o=i.owner||db.owner;let type=r?'ใบเสร็จรับเงิน':i.state==='void'?'ใบแจ้งหนี้ (ยกเลิก)':'ใบแจ้งหนี้';let html=(demo?'<div class="demo-watermark">ข้อมูลตัวอย่าง · ไม่ใช่เอกสารเรียกเก็บเงินจริง</div>':'')+'<h1>'+type+'</h1><div class="print-meta"><div><b>'+E(o.building||'โกดังให้เช่า')+'</b><br>'+E(o.name)+'<br>'+E(o.address||'')+'<br>โทร '+E(o.phone||'—')+'</div><div>เลขที่ '+E(r?r.number:i.number)+'<br>วันที่ '+date(r?r.date:i.createdAt)+'<br>รอบ '+month(i.period)+'<br>กำหนดชำระ '+date(i.due)+'</div></div><hr style="margin:20px 0"><b>ผู้เช่า '+E(i.tenantName)+' · '+E(i.roomName)+'</b><table><thead><tr><th>รายการ</th><th class="num">จำนวนเงิน (บาท)</th></tr></thead><tbody>'+[['ค่าเช่า',i.rent],['ค่าน้ำ',i.water],['ค่าไฟ',i.electric],['อื่น ๆ',i.other]].filter(x=>x[1]||x[0]==='ค่าเช่า').map(([k,v])=>'<tr><td>'+k+'</td><td class="num">'+M(v)+'</td></tr>').join('')+'<tr><td><b>รวมใบแจ้งหนี้</b></td><td class="num"><b>'+M(i.total)+'</b></td></tr>'+(r?'<tr><td><b>รับเงินครั้งนี้ · '+E(r.method)+'</b></td><td class="num"><b>'+M(r.amount)+'</b></td></tr>':'')+'</tbody></table>'+(i.snapshot?['water','electric'].map(k=>{let s=i.snapshot[k];return(k==='water'?'ค่าน้ำ':'ค่าไฟ')+': มิเตอร์ '+s.previous+' → '+s.current+' = '+s.units+' หน่วย × '+s.rate.toFixed(6)+' บาท<br>';}).join(''):'')+'<br><b>ยอดคงเหลือปัจจุบัน '+M(i.state==='void'?0:RP.balance(db,i))+' บาท</b><br>'+E(r?r.note||'':i.note||'')+(!r?'<br>บัญชีรับชำระ '+E(o.bank||'—'):'')+'<div class="sign"><span>ผู้'+(r?'รับเงิน':'ออกเอกสาร')+' ................................</span><span>วันที่ ................................</span></div><footer>ค่าน้ำ–ค่าไฟคิดตามต้นทุนบิลจริง ไม่มีบวกเพิ่ม · เอกสารนี้ไม่ใช่ใบกำกับภาษี</footer>';$('print').innerHTML=html;window.print();}
function contractDetail(id){let c=db.contracts.find(x=>x.id===id);if(!c)throw Error('ไม่พบสัญญา');let r=db.rooms.find(r=>r.id===c.roomId),t=db.tenants.find(t=>t.id===c.tenantId),pair=(k,v)=>'<div><span class="key">'+k+'</span><div class="value">'+E(v||'—')+'</div></div>';modal('สัญญาเช่า · '+E(r?.name||''),(demo?'<div class="notice warn">ข้อมูลสัญญาตัวอย่างสำหรับทดลองระบบ</div>':'')+'<div class="details-grid">'+pair('เลขที่สัญญา',c.number||c.id)+pair('วันทำสัญญา',date(c.signedDate||c.startDate))+pair('ผู้ให้เช่า',db.owner.name)+pair('ผู้เช่า',tenant(c.tenantId))+pair('ที่ตั้งพื้นที่เช่า',db.owner.propertyAddr||db.owner.address)+pair('ขนาดพื้นที่',r?.size?r.size+' ตร.ม.':'—')+pair('วันเริ่ม – วันสิ้นสุด',date(c.startDate)+' – '+date(c.endDate))+pair('วันส่งมอบ',date(c.handoverDate||c.startDate))+pair('ค่าเช่าต่อเดือน',M(c.rent)+' บาท')+pair('กำหนดชำระ','วันที่ '+(c.dueDay||1)+' ของเดือน')+pair('เงินประกัน',M(c.deposit)+' บาท')+pair('ค่าเช่าล่วงหน้า',M(c.advance)+' บาท')+pair('ผู้ประสานงาน',c.tenantContact||t?.contactPerson)+pair('ช่องทางติดต่อ',t?.phone)+pair('วัตถุประสงค์',c.permittedUse||c.purpose)+pair('เลขมิเตอร์น้ำ / ไฟ',(c.waterMeterNo||'—')+' / '+(c.electricMeterNo||'—'))+'</div><h3 style="font-size:14px;margin-top:25px">เงื่อนไขและหมายเหตุ</h3><div class="value" style="white-space:pre-wrap">'+E(c.terms||'ยังไม่ระบุเงื่อนไข')+'</div>',btn('ปิด','close')+btn('แก้ไขสัญญา','edit-contract','','data-id="'+id+'"')+btn('พิมพ์สรุปสัญญา','print-contract','primary','data-id="'+id+'"'),true);}
function printContractSummary(id){let c=db.contracts.find(c=>c.id===id),r=db.rooms.find(r=>r.id===c.roomId);$('print').innerHTML=(demo?'<div class="demo-watermark">ข้อมูลสาธิต</div>':'')+'<h1>สรุปข้อมูลสัญญาเช่า</h1><p>เลขที่ '+E(c.number||c.id)+' · วันทำสัญญา '+date(c.signedDate||c.startDate)+'</p><b>'+E(r.name)+' · '+E(tenant(c.tenantId))+'</b><p>เริ่ม '+date(c.startDate)+' ถึง '+date(c.endDate)+'<br>ค่าเช่า '+M(c.rent)+' บาท / เดือน<br>เงินประกัน '+M(c.deposit)+' บาท<br>ค่าเช่าล่วงหน้า '+M(c.advance)+' บาท<br>กำหนดชำระวันที่ '+c.dueDay+' ของเดือน</p><h3>เงื่อนไขที่บันทึกไว้</h3><p style="white-space:pre-wrap">'+E(c.terms||'ไม่ระบุ')+'</p><footer>สรุปข้อมูลเพื่อการจัดการ ไม่ใช่สัญญาสำหรับลงนาม</footer>';window.print();}
function download(filename,value){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){let rows=[['เลขที่','รอบ','โกดัง','ผู้เช่า','ค่าเช่า','ค่าน้ำ','ค่าไฟ','รวม','คงเหลือ','สถานะ'],...db.rp3.invoices.filter(i=>allPeriods||i.period===period).map(i=>[i.number,i.period,i.roomName,i.tenantName,i.rent,i.water,i.electric,i.total,i.state==='void'?0:RP.balance(db,i),status(i)])],text='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='RentPro-'+(demo?'demo-':'')+period+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function firebase(){if(demo)throw Error('ข้อมูลตัวอย่างไม่เชื่อมต่อคลาวด์');let cfg=db.fbcfg;if(!cfg?.projectId)throw Error('ยังไม่ได้ตั้งค่า Firebase');if(!window.firebase){for(const src of ['https://www.gstatic.com/firebasejs/10.7.1/firebase-app-compat.js','https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore-compat.js'])await new Promise((resolve,reject)=>{let script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=()=>reject(Error('โหลดการเชื่อมต่อคลาวด์ไม่ได้'));document.head.appendChild(script);});}let app=window.firebase.apps.find(a=>a.options.projectId===cfg.projectId)||window.firebase.initializeApp({apiKey:cfg.apiKey,projectId:cfg.projectId,authDomain:cfg.authDomain},'rentpro-'+cfg.projectId);fb=app.firestore();return fb;}
async function sync(){if(demo)throw Error('โหมดสาธิตไม่ส่งข้อมูลไปคลาวด์');if(busy)throw Error('กำลังซิงค์ข้อมูล กรุณารอสักครู่');busy=true;cloudError='';renderStatus();try{await rpStore.flush();await firebase();let captured=C(db),local=C(db),merged;for(let attempt=0;attempt<3;attempt++){let read=await RPCloud.read(fb),remote=read.data||C(base);if(!knownBase&&read.data){let blank={rooms:[],tenants:[],contracts:[],payments:[],owner:{},schemaVersion:3,rp3:{cycles:[],invoices:[],receipts:[],audit:[]}};if(remote.rooms.length&&!local.tenants.length&&!local.contracts.length&&!local.payments.length&&local.rooms.every(r=>/^warehouse-[1-4]$/.test(r.id)&&!r.rent))local.rooms=[];merged=RP.merge(blank,local,remote);}else merged=RP.merge(base,local,remote);delete merged._demo;merged.updatedAt=now();try{await RPCloud.commit(fb,read,merged);break;}catch(e){if(e.retryable&&attempt<2)continue;throw e;}}base=C(merged);knownBase=true;rpStore.setItem('rentpro_v3_confirmed_base',JSON.stringify(base));if(JSON.stringify(db)===JSON.stringify(captured)){db=merged;rpStore.removeItem('rentpro_v3_pending');}else db=RP.merge(captured,db,merged);RentModel.syncPayments(db,today);rpStore.setItem('rentpro_v2',JSON.stringify(db));cloudReady=true;cloudError='';if(page!=='billing'&&!$('modal'))render();}catch(e){cloudError=e.message;throw e;}finally{busy=false;renderStatus();}}
async function pullCloud(){await firebase();let read=await RPCloud.read(fb);if(!read.data)throw Error('ไม่พบข้อมูลในคลาวด์');rpStore.setItem('rentpro_backup_before_cloud_pull',JSON.stringify({at:now(),data:db}));let data=RP.validate(read.data);['fbcfg','gsync','notify','lineNotify'].forEach(k=>{if(db[k])data[k]=db[k];});delete data._demo;db=data;base=C(data);knownBase=true;cloudReady=true;cloudError='';rpStore.setItem('rentpro_v2',JSON.stringify(db));rpStore.setItem('rentpro_v3_confirmed_base',JSON.stringify(base));rpStore.removeItem('rentpro_v3_pending');working=null;render();toast('โหลดข้อมูลคลาวด์แล้ว');}
async function act(action,b){let id=b.dataset.id;switch(action){case 'close':close();break;case 'go-billing':nav('billing');break;case 'go-payments':nav('payments');break;case 'go-cloud':settingsTab='cloud';nav('settings');break;case 'show-overdue':page='payments';filter='overdue';allPeriods=true;working=null;render();break;case 'switch-mode':cacheDraft();rpStore.setItem('rentpro_v4_mode',demo?'real':'demo');await rpStore.flush();{let url=new URL(demo?'index.html':'demo.html',location.href);if(demo)url.searchParams.set('mode','real');url.hash=demo?'overview':'properties';location.assign(url.href);}break;case 'reset-demo':if(!demo)return;modal('เริ่มชุดตัวอย่างใหม่','ข้อมูลที่พี่ทดลองแก้ไขในโหมดตัวอย่างจะถูกแทนด้วยตัวอย่างครบ 4 หลัง ข้อมูลจริงยังคงอยู่',btn('ย้อนกลับ','close')+btn('เริ่มตัวอย่างใหม่','confirm-reset','primary'));break;case 'confirm-reset':if(!demo)return;db=rentDemo(today);rpStore.setItem('rentpro_demo_v4',JSON.stringify(db));for(let key of rpStore.keys())if(key.startsWith('rentpro_demo_draft_'))rpStore.removeItem(key);working=null;selectedRoom=db.rooms[0].id;close();render();toast('เตรียมตัวอย่างครบ 4 หลังแล้ว');break;case 'stage-one':cacheDraft();stage=1;render();break;case 'stage-prev':cacheDraft();stage=Math.max(1,stage-1);render();break;case 'stage-next':cacheDraft();if(stage===1){for(const k of ['water','electric']){let c=getWorking(),fake=[{roomId:'validate',waterPrev:0,waterNow:0,electricPrev:0,electricNow:0}];RP.calcUtility(c[k],fake,k);if(!c[k].from||!c[k].to||c[k].from>c[k].to)throw Error('กรอกช่วงวันที่บิลหลักให้ครบ');}}stage=Math.min(3,stage+1);render();break;case 'save-draft':draftSave();break;case 'issue-preview':issuePreview();break;case 'confirm-issue':{let c=getWorking();if(c.state==='issued')throw Error('รอบนี้ออกบิลแล้ว');let result=RentModel.build(db,c,uid,now());c.state='issued';c.issuedAt=now();c.calculation=result.calculation;let idx=db.rp3.cycles.findIndex(x=>x.id===c.id);if(idx<0)db.rp3.cycles.push(C(c));else db.rp3.cycles[idx]=C(c);db.rp3.invoices.push(...result.invoices);rpStore.removeItem((demo?'rentpro_demo_draft_':'rentpro_draft_')+period);save('ออกใบแจ้งหนี้ '+result.invoices.length+' หลัง',c.id);close();working=null;page='payments';render();toast('ออกใบแจ้งหนี้แล้ว');break;}case 'detail':detail(id);break;case 'receive':receiveModal(id);break;case 'save-receipt':{let value=formValues('receive-form');if(modalData.loading)throw Error('กำลังอ่านหลักฐาน กรุณารอสักครู่');if(modalData.proof)value.proof=modalData.proof;let r=RentModel.receive(db,id,value,uid(),today);save('รับชำระ '+M(r.amount)+' บาท',r.id);close();render();toast('บันทึกรับเงินแล้ว');break;}case 'print-invoice':printDocument(id);break;case 'print-receipt':{let r=db.rp3.receipts.find(r=>r.id===id);if(r)printDocument(r.invoiceId,id);break;}case 'view-bill':imageModal(getWorking()[b.dataset.kind].attachment);break;case 'view-proof':imageModal(db.rp3.receipts.find(r=>r.id===id)?.proof);break;case 'void-receipt':reasonModal('ยกเลิกรายการรับเงิน','receipt',id,'จะเก็บรายการเดิมไว้ พร้อมคืนยอดค้างในใบแจ้งหนี้');break;case 'confirm-receipt':{let reason=formValues('reason-form').reason.trim();if(!reason)throw Error('ระบุเหตุผลก่อนยืนยัน');let r=db.rp3.receipts.find(x=>x.id===id);if(!r||r.voided)throw Error('รายการนี้ถูกยกเลิกแล้ว');r.voided=true;r.voidReason=reason;r.voidedAt=now();save('ยกเลิกรับชำระ: '+reason,id);close();render();toast('ยกเลิกการรับเงินแล้ว');break;}case 'void-invoice':{if(db.rp3.receipts.some(r=>r.invoiceId===id&&!r.voided))throw Error('ต้องยกเลิกรายการรับเงินก่อนยกเลิกบิล');reasonModal('ยกเลิกใบแจ้งหนี้','invoice',id,'เก็บเลขที่และเหตุผลการยกเลิกไว้ในประวัติ');break;}case 'confirm-invoice':{let reason=formValues('reason-form').reason.trim();if(!reason)throw Error('ระบุเหตุผลก่อนยืนยัน');if(db.rp3.receipts.some(r=>r.invoiceId===id&&!r.voided))throw Error('ยังมีรายการรับเงินในบิลนี้');let i=db.rp3.invoices.find(i=>i.id===id);i.state='void';i.voidReason=reason;i.voidedAt=now();save('ยกเลิกใบแจ้งหนี้: '+reason,id);close();render();break;}case 'cancel-cycle':{let c=getWorking(),ids=db.rp3.invoices.filter(i=>i.cycleId===c.id&&i.state!=='void').map(i=>i.id);if(db.rp3.receipts.some(r=>ids.includes(r.invoiceId)&&!r.voided))throw Error('รอบนี้มีการรับชำระแล้ว ต้องยกเลิกรายการรับเงินก่อน');reasonModal('ยกเลิกรอบบิล','cycle',c.id,'ใบแจ้งหนี้ในรอบนี้จะถูกยกเลิก เพื่อให้แก้เลขมิเตอร์และออกใหม่ได้');break;}case 'confirm-cycle':{let reason=formValues('reason-form').reason.trim();if(!reason)throw Error('ระบุเหตุผลก่อนยืนยัน');let ids=db.rp3.invoices.filter(i=>i.cycleId===id&&i.state!=='void').map(i=>i.id);if(db.rp3.receipts.some(r=>ids.includes(r.invoiceId)&&!r.voided))throw Error('ยังมีรายการรับเงินในรอบนี้');db.rp3.invoices.filter(i=>ids.includes(i.id)).forEach(i=>{i.state='void';i.voidReason=reason;});let c=db.rp3.cycles.find(x=>x.id===id);c.state='void';c.voidReason=reason;save('ยกเลิกรอบบิล: '+reason,id);working=null;stage=1;close();render();break;}case 'add-room':roomModal();break;case 'edit-room':roomModal(id);break;case 'save-room':{let value=formValues('room-form');if(db.rooms.some(r=>!r.archived&&r.id!==id&&r.name.trim().toLowerCase()===value.name.trim().toLowerCase()))throw Error('ชื่อโกดังนี้มีอยู่แล้ว');let r=db.rooms.find(r=>r.id===id);let updated={...r,...value,id:id||uid(),rent:Number(value.rent),size:Number(value.size),type:'โกดัง'};if(r)db.rooms[db.rooms.indexOf(r)]=updated;else db.rooms.push(updated);selectedRoom=updated.id;save('บันทึกข้อมูลโกดัง',updated.id);close();render();break;}case 'archive-room':if(db.contracts.some(c=>!c.archived&&c.roomId===id&&c.endDate>=today))throw Error('โกดังยังมีสัญญาใช้งานหรือรอเริ่ม ต้องยุติสัญญาก่อน');reasonModal('ปิดใช้งานโกดัง','room',id,'ประวัติผู้เช่าและบิลเดิมยังดูย้อนหลังได้');break;case 'confirm-room':{let reason=formValues('reason-form').reason.trim();if(!reason)throw Error('ระบุเหตุผลก่อนยืนยัน');let r=db.rooms.find(r=>r.id===id);r.archived=true;save('ปิดใช้งานโกดัง: '+reason,id);selectedRoom='';close();render();break;}case 'edit-tenant':tenantModal(id);break;case 'save-tenant':{let value=formValues('tenant-form'),t=db.tenants.find(t=>t.id===id);Object.assign(t,value);save('แก้ไขข้อมูลผู้เช่า',id);close();render();break;}case 'new-contract':contractModal(null,id);break;case 'edit-contract':contractModal(id);break;case 'save-contract':{let value=formValues('contract-form'),roomId=b.dataset.roomid;if(!Number.isInteger(Number(value.dueDay))||Number(value.dueDay)<1||Number(value.dueDay)>31)throw Error('กำหนดชำระต้องเป็นวันที่ 1 ถึง 31');if(value.startDate>value.endDate)throw Error('วันสิ้นสุดต้องไม่น้อยกว่าวันเริ่มสัญญา');if(db.contracts.some(c=>!c.archived&&c.id!==id&&c.roomId===roomId&&c.startDate<=value.endDate&&c.endDate>=value.startDate))throw Error('โกดังมีสัญญาทับช่วงเวลาอยู่แล้ว');let tenantId=value.tenantId;if(tenantId==='new'){if(!value.newName.trim())throw Error('กรอกชื่อผู้เช่าหรือกิจการ');tenantId=uid();db.tenants.push({id:tenantId,prefix:'',fname:value.newName.trim(),lname:'',phone:value.newPhone});}if(!db.tenants.some(t=>t.id===tenantId))throw Error('เลือกผู้เช่าก่อน');if(value.number&&db.contracts.some(c=>c.id!==id&&c.number===value.number.trim()))throw Error('เลขที่สัญญาซ้ำกับรายการเดิม');let c=db.contracts.find(c=>c.id===id);if(c)db.rp3.audit.push({id:uid(),at:now(),action:'เก็บข้อมูลสัญญาก่อนแก้ไข',ref:id,before:C(c)});let updated={...c,id:id||uid(),roomId,tenantId,startDate:value.startDate,endDate:value.endDate,rent:Number(value.rent),deposit:Number(value.deposit),advance:Number(value.advance),dueDay:Number(value.dueDay),terms:value.terms,number:value.number.trim(),signedDate:value.signedDate,handoverDate:value.handoverDate,tenantContact:value.tenantContact,ownerContact:value.ownerContact,permittedUse:value.permittedUse,waterMeterNo:value.waterMeterNo,electricMeterNo:value.electricMeterNo,waterType:'actual',electricType:'actual',purpose:'เพื่อประกอบธุรกิจ',status:'active'};if(c)db.contracts[db.contracts.indexOf(c)]=updated;else db.contracts.push(updated);save('บันทึกสัญญา',updated.id);close();render();break;}case 'end-contract':reasonModal('ยุติสัญญา','contract',id,'ไม่ลบสัญญาและประวัติบิลเดิม ยอดค้างยังต้องติดตามต่อ');break;case 'confirm-contract':{let reason=formValues('reason-form').reason.trim();if(!reason)throw Error('ระบุเหตุผลก่อนยืนยัน');let c=db.contracts.find(c=>c.id===id);c.archived=true;c.status='terminated';c.terminatedAt=now();c.terminationReason=reason;save('ยุติสัญญา: '+reason,id);close();render();break;}case 'view-contract':contractDetail(id);break;case 'print-contract':printContractSummary(id);break;case 'save-owner':{let value=formValues('owner-form');db.owner={...db.owner,...value};save('บันทึกข้อมูลผู้ให้เช่า');render();toast('บันทึกข้อมูลผู้ให้เช่าแล้ว');break;}case 'save-cloud':{if(demo)throw Error('ตั้งค่าคลาวด์ในโหมดข้อมูลจริงเท่านั้น');let value=formValues('cloud-form'),old=db.fbcfg?.projectId;db.fbcfg=value;if(old!==value.projectId){knownBase=false;cloudReady=false;fb=null;base=C(db);rpStore.removeItem('rentpro_v3_confirmed_base');rpStore.removeItem('rentpro_v3_sync_base');}save('บันทึกการเชื่อมต่อคลาวด์');toast('บันทึกการเชื่อมต่อแล้ว');break;}case 'sync':await sync();render();toast('ซิงค์ข้อมูลสำเร็จ');break;case 'pull-cloud':if(demo)throw Error('โหมดตัวอย่างไม่โหลดข้อมูลจริง');modal('โหลดข้อมูลจากคลาวด์','ข้อมูลปัจจุบันในเครื่องจะถูกสำรองก่อนโหลดมาแทน หากมีข้อมูลรอซิงค์ ควรดาวน์โหลดสำรองเก็บไว้ด้วย',btn('ย้อนกลับ','close')+btn('โหลดข้อมูล','confirm-pull','primary'));break;case 'confirm-pull':if(demo)throw Error('ไม่โหลดข้อมูลจริงเข้าโหมดตัวอย่าง');close();await pullCloud();break;case 'export':download('RentPro-'+(demo?'demo-':'real-')+today+'.json',{format:'rentpro-v4',exportedAt:now(),data:db});break;case 'export-old':{let old=rpStore.getItem('rentpro_backup_before_v4');if(!old)throw Error('ไม่มีข้อมูลก่อนปรับรุ่นในเครื่องนี้');download('RentPro-before-v4.json',JSON.parse(old));break;}case 'csv':exportCSV();break;}}
document.addEventListener('click',async e=>{let navButton=e.target.closest('[data-nav]');if(navButton){nav(navButton.dataset.nav);return;}let room=e.target.closest('[data-room]');if(room){selectedRoom=room.dataset.room;nav('properties');return;}let b=e.target.closest('button');if(!b)return;try{if(b.dataset.stage){cacheDraft();stage=Number(b.dataset.stage);render();return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.setting){settingsTab=b.dataset.setting;render();return;}if(b.dataset.action)await act(b.dataset.action,b);}catch(error){message(error);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-room]')){e.preventDefault();selectedRoom=e.target.dataset.room;nav('properties');}});
let cacheTimer;document.addEventListener('input',e=>{let el=e.target;if(el.id==='search'){search=el.value;let pos=el.selectionStart;render();let s=$('search');s?.focus();if(s?.setSelectionRange)s.setSelectionRange(pos,pos);return;}if(page!=='billing'||el.closest('#modal'))return;let c=getWorking();if(c.state==='issued')return;if(el.dataset.read){let row=c.rows.find(r=>r.roomId===el.dataset.roomid);row[el.dataset.read]=el.value;let k=el.dataset.read.startsWith('water')?'water':'electric';let cell=$('use-'+k+'-'+row.roomId);if(cell)cell.textContent=row[k+'Now']!==''&&row[k+'Prev']!==''?Number((Number(row[k+'Now'])-Number(row[k+'Prev'])).toFixed(6)):'—';}else if(el.name){let parts=el.name.match(/^(water|electric)-(.+)$/);if(parts){c[parts[1]][parts[2]]=el.value;let total=$('total-'+parts[1]);if(total)total.textContent='฿'+M(billSum(c[parts[1]]));}else if(['due','note'].includes(el.name))c[el.name]=el.value;}clearTimeout(cacheTimer);cacheTimer=setTimeout(cacheDraft,350);});
document.addEventListener('change',async e=>{let el=e.target;try{if(el.id==='period'){cacheDraft();period=el.value||today.slice(0,7);working=null;render();}if(el.id==='all-periods'){allPeriods=el.checked;render();}if(el.dataset.file&&el.files[0]){let file=el.files[0],kind=el.dataset.file;if(file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('ใช้ภาพ PNG / JPEG / WebP ขนาดไม่เกิน 5 MB ต่อภาพ');let target=kind==='proof'?modalData:getWorking();if(kind!=='proof'&&target.state==='issued')throw Error('บิลรอบนี้ล็อกแล้ว');if(kind==='proof')modalData.loading=true;try{let imageData=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('อ่านไฟล์ไม่สำเร็จ'));r.readAsDataURL(file);}),assetId=crypto.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join(''):uid();let image={name:file.name,assetId,data:imageData};if(kind==='proof'&&target!==modalData)return;if(kind==='proof'){target.proof=image;target.loading=false;if($('proof-name'))$('proof-name').textContent='แนบแล้ว: '+file.name;}else{target[kind].attachment=image;rpStore.setItem((demo?'rentpro_demo_draft_':'rentpro_draft_')+target.period,JSON.stringify(target));if(page==='billing'&&working===target)render();}}catch(error){if(kind==='proof')target.loading=false;throw error;}}if(el.id==='import'&&el.files[0]){let parsed=JSON.parse(await el.files[0].text()),data=parsed.data||parsed;if(!Array.isArray(data.rooms)||!Array.isArray(data.tenants)||!Array.isArray(data.contracts)||!Array.isArray(data.payments))throw Error('ไฟล์นี้ไม่ใช่ข้อมูล RentPro');if(Boolean(data._demo)!==demo)throw Error('ไฟล์สำรองต้องตรงกับโหมดข้อมูลจริง / ตัวอย่างที่กำลังเปิด');RP.migrate(data);let blank={rooms:[],tenants:[],contracts:[],payments:[],owner:{},schemaVersion:3,rp3:{cycles:[],invoices:[],receipts:[],audit:[]}},merged=RP.merge(blank,db,data);rpStore.setItem(demo?'rentpro_demo_before_import':'rentpro_backup_before_import',JSON.stringify({at:now(),data:db}));db=merged;save('นำเข้าข้อมูลจากไฟล์สำรอง');working=null;render();toast('นำเข้าข้อมูลแล้ว');}}catch(error){message(error);if(el.type==='file')el.value='';}});
window.addEventListener('rentpro-storage-error',e=>{cloudError='บันทึกในเครื่องไม่สำเร็จ: '+e.detail;renderStatus();toast(cloudError+' กรุณาดาวน์โหลดสำรอง');});
async function refreshCloud(){if(demo||!cloudReady||busy||isDirty()||working||$('modal')||document.visibilityState==='hidden')return;try{let result=await RPCloud.read(fb);if(!result.data)return;db=RP.merge(base,db,result.data);base=C(db);rpStore.setItem('rentpro_v3_confirmed_base',JSON.stringify(base));rpStore.setItem('rentpro_v2',JSON.stringify(db));render();}catch(e){cloudError=e.message;renderStatus();}}
setInterval(refreshCloud,60000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')cacheDraft();else refreshCloud();});window.addEventListener('beforeunload',cacheDraft);window.addEventListener('online',()=>{if(!demo&&isDirty()&&(db.fbcfg||{}).auto!=='off')sync().catch(()=>{});});
rpStore.setItem(demo?'rentpro_demo_v4':'rentpro_v2',JSON.stringify(db));render();if(!demo&&(db.fbcfg||{}).projectId&&(db.fbcfg||{}).auto!=='off')sync().catch(e=>{cloudError=e.message;render();});
})();
